<?php
require_once __DIR__.'/../config/db.php';
$notice='';$ok=false;
if($_SERVER['REQUEST_METHOD']==='POST'){
 $nombre=trim($_POST['nombre']??'');$correo=trim($_POST['correo']??'');$mensaje=trim($_POST['mensaje']??'');
 if($nombre!=='' && filter_var($correo,FILTER_VALIDATE_EMAIL) && $mensaje!==''){
  $stmt=$pdo->prepare('INSERT INTO mensajes(nombre,correo,mensaje) VALUES(?,?,?)');$stmt->execute([$nombre,$correo,$mensaje]);$notice='Tu mensaje fue guardado correctamente.';$ok=true;
 }else{$notice='Revisa los campos: todos son obligatorios y el correo debe ser válido.';}
}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ejercicio 02 | Contacto</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><header class="topbar"><a class="brand" href="../index.php"><span class="brand-mark">P</span> PWATAREA3</a><a class="back" href="../index.php">← Volver al inicio</a></header><main class="page-wrap"><span class="eyebrow">EJERCICIO 02</span><section class="panel"><h1>Formulario de contacto</h1><p class="muted">Completa los campos. JavaScript valida antes del envío y PHP vuelve a comprobar los datos y los almacena en MySQL.</p><?php if($notice): ?><p class="notice"><?=htmlspecialchars($notice)?></p><?php endif; ?><form class="form-grid" id="contactForm" method="post"><label>Nombre<input name="nombre" id="nombre" maxlength="100" required></label><label>Correo electrónico<input type="email" name="correo" id="correo" required></label><label>Mensaje<textarea name="mensaje" id="mensaje" required></textarea></label><button class="btn-submit">Enviar mensaje</button><span class="small" id="formError"></span></form></section></main><script>document.getElementById('contactForm').addEventListener('submit',e=>{const n=document.getElementById('nombre').value.trim(),c=document.getElementById('correo').value.trim(),m=document.getElementById('mensaje').value.trim(),err=document.getElementById('formError');if(!n||!c||!m||!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(c)){e.preventDefault();err.textContent='Completa todos los campos e ingresa un correo válido.';}});</script></body></html>